INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (136, 'hotPessoalBase', 'Mount de Pessoal em 1 ida (CICLOS,CRS,BENEFICIOS,ENCARGOS). Param: cicloId (0 = ciclo aberto default).', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''ANO'',t.ANO,''STATUS'',t.STATUS,''CRIADO_EM'',t.CRIADO_EM,''VERSAO_ATUAL'',t.VERSAO_ATUAL,''ULTIMO_MES_REALIZADO'',t.ULTIMO_MES_REALIZADO,''VERSAO_CONTROLE'',t.VERSAO_CONTROLE,''VERSAO_ORIGEM_ID'',t.VERSAO_ORIGEM_ID,''CRIADO_POR'',t.CRIADO_POR)) FROM CICLO t WHERE t.STATUS != ''FECHADO''),JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''TIPO'',t.TIPO,''VALOR'',t.VALOR,''PERCENTUAL'',t.PERCENTUAL,''APLICA_PJ'',t.APLICA_PJ,''APLICA_CLT'',t.APLICA_CLT,''CICLO_ID'',t.CICLO_ID)) FROM BENEFICIO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE (SELECT ID FROM CICLO WHERE STATUS != ''FECHADO'' ORDER BY ANO DESC, ID DESC LIMIT 1) END),JSON_ARRAY()) AS BENEFICIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''PERCENTUAL'',t.PERCENTUAL,''APLICA_PJ'',t.APLICA_PJ,''APLICA_CLT'',t.APLICA_CLT,''CICLO_ID'',t.CICLO_ID)) FROM ENCARGO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE (SELECT ID FROM CICLO WHERE STATUS != ''FECHADO'' ORDER BY ANO DESC, ID DESC LIMIT 1) END),JSON_ARRAY()) AS ENCARGOS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
